import React, {useEffect, useState} from 'react';
import {
	AbsoluteFill,
	continueRender,
	delayRender,
	interpolate,
	useCurrentFrame,
	useVideoConfig,
} from 'remotion';
import {noise2D} from '@remotion/noise';

/* ------------------------------------------------------------------ *
 *  AUTONOMOUS FREIGHT — LiDAR PERCEPTION CONSOLE
 *  1920x1080 | 60fps | 15s
 *
 *  The truck, the road furniture, the traffic and the ground returns
 *  are one procedurally baked point cloud (deterministic LCG, seeded
 *  once at module scope) projected with hand-rolled perspective maths.
 *  No WebGL, no imported 3D model, nothing to attribute.
 * ------------------------------------------------------------------ */

/* --- Inter (SIL OFL 1.1) subset, embedded self-contained --- */
const FONT = 'InterFleet';
const F5 = '';
const F7 = '';
const F8 = '';
let fontRequested = false;
const ensureFont = () => {
	if (fontRequested || typeof document === 'undefined') return;
	fontRequested = true;
	const el = document.createElement('style');
	const face = (w: number, b: string) =>
		"@font-face{font-family:'" + FONT + "';font-style:normal;font-weight:" + w +
		';font-display:block;src:url(data:font/woff2;base64,' + b + ") format('woff2');}";
	el.textContent = face(500, F5) + face(700, F7) + face(800, F8);
	document.head.appendChild(el);
};

const W = 1920;
const H = 1080;
const TAU = Math.PI * 2;

/* ---------------- palette ---------------- */
const MAG = '#FF46D8';
const MAG_HI = '#FFC6F2';
const VIO = '#9B6BFF';
const CYA = '#46E8FF';
const AMB = '#FFB648';
const GRN = '#4BE9A8';
const RED = '#FF5E82';
const INK = '#F5ECFF';
const DIM = '#A98CD6';
const DIM2 = '#6E559B';
const HAIR = 'rgba(168,120,224,0.20)';
const HAIR2 = 'rgba(168,120,224,0.34)';

/* ---------------- layout ---------------- */
const M = 56;
const COLW = 330;
const VX = M + COLW + 14;
const VY = 118;
const VW = W - 2 * M - 2 * COLW - 28;
const VH = 694;
const RX = VX + VW + 14;

/* ---------------- colour helpers ---------------- */
const hx = (c: string) => [
	parseInt(c.slice(1, 3), 16),
	parseInt(c.slice(3, 5), 16),
	parseInt(c.slice(5, 7), 16),
];
const mix2 = (a: string, b: string, t: number) => {
	const A = hx(a);
	const B = hx(b);
	const f = (i: number) => Math.round(A[i] + (B[i] - A[i]) * t);
	return 'rgb(' + f(0) + ',' + f(1) + ',' + f(2) + ')';
};
const ramp3 = (a: string, b: string, c: string, t: number) =>
	t < 0.5 ? mix2(a, b, t * 2) : mix2(b, c, (t - 0.5) * 2);

const NB = 9;
const COL_TRUCK = Array.from({length: NB}, (_, i) =>
	ramp3('#3A1C78', '#FF3FD1', '#FFE9FA', i / (NB - 1))
);
const COL_GRND = Array.from({length: NB}, (_, i) =>
	ramp3('#170E35', '#7C3FD2', '#FF9DEE', i / (NB - 1))
);
const COL_OBJ = Array.from({length: NB}, (_, i) =>
	ramp3('#150B31', '#6C3FC4', '#C79CF0', i / (NB - 1))
);

/* ================================================================== *
 *  DETERMINISTIC POINT-CLOUD BAKERY
 * ================================================================== */
let _s = 0x5f3a91c7 >>> 0;
const rr = () => {
	_s = (Math.imul(_s, 1664525) + 1013904223) >>> 0;
	return _s / 4294967296;
};

type Pt = {x: number; y: number; z: number; i: number};

/* nominal sensor direction, used to bake facing-dependent return
   strength — the camera only drifts a few degrees so this holds */
const VD = [-0.819, -0.156, 0.552];
const faceVis = (nx: number, ny: number, nz: number) =>
	0.3 + 0.7 * Math.max(0, -(nx * VD[0] + ny * VD[1] + nz * VD[2]));

const shell = (
	out: Pt[],
	x0: number,
	x1: number,
	y0: number,
	y1: number,
	z0: number,
	z1: number,
	dens: number,
	gain: number,
	skip: string
) => {
	const LX = x1 - x0;
	const LY = y1 - y0;
	const LZ = z1 - z0;
	const F = (
		area: number,
		nx: number,
		ny: number,
		nz: number,
		g: (u: number, v: number) => number[]
	) => {
		const vis = faceVis(nx, ny, nz);
		const n = Math.max(2, Math.round(area * dens * (0.56 + 0.44 * vis)));
		for (let q = 0; q < n; q++) {
			const p = g(rr(), rr());
			out.push({x: p[0], y: p[1], z: p[2], i: gain * vis * (0.78 + rr() * 0.38)});
		}
	};
	if (skip.indexOf('a') < 0) F(LY * LZ, -1, 0, 0, (u, v) => [x0, y0 + u * LY, z0 + v * LZ]);
	if (skip.indexOf('b') < 0) F(LY * LZ, 1, 0, 0, (u, v) => [x1, y0 + u * LY, z0 + v * LZ]);
	if (skip.indexOf('c') < 0) F(LX * LZ, 0, -1, 0, (u, v) => [x0 + u * LX, y0, z0 + v * LZ]);
	if (skip.indexOf('d') < 0) F(LX * LZ, 0, 1, 0, (u, v) => [x0 + u * LX, y1, z0 + v * LZ]);
	if (skip.indexOf('e') < 0) F(LX * LY, 0, 0, -1, (u, v) => [x0 + u * LX, y0 + v * LY, z0]);
	if (skip.indexOf('f') < 0) F(LX * LY, 0, 0, 1, (u, v) => [x0 + u * LX, y0 + v * LY, z1]);
};

const beam = (
	out: Pt[],
	ax: number,
	ay: number,
	az: number,
	bx: number,
	by: number,
	bz: number,
	per: number,
	gain: number
) => {
	const L = Math.hypot(bx - ax, by - ay, bz - az);
	const n = Math.max(2, Math.round(L * per));
	for (let q = 0; q <= n; q++) {
		const s = q / n;
		out.push({
			x: ax + (bx - ax) * s,
			y: ay + (by - ay) * s,
			z: az + (bz - az) * s,
			i: gain * (0.84 + rr() * 0.3),
		});
	}
};

const boxEdges = (
	out: Pt[],
	x0: number,
	x1: number,
	y0: number,
	y1: number,
	z0: number,
	z1: number,
	per: number,
	gain: number
) => {
	const X = [x0, x1];
	const Y = [y0, y1];
	const Z = [z0, z1];
	const zg = [1, 0.38];
	const xg = [0.48, 1];
	for (let a = 0; a < 2; a++) {
		for (let b = 0; b < 2; b++) {
			beam(out, x0, Y[a], Z[b], x1, Y[a], Z[b], per, gain * zg[b]);
			beam(out, X[a], y0, Z[b], X[a], y1, Z[b], per, gain * zg[b] * xg[a]);
			beam(out, X[a], Y[b], z0, X[a], Y[b], z1, per, gain * xg[a]);
		}
	}
};

