shell(TRUCK, -1.8, -1.5, 0.14, 1.42, 0.78, 1.02, 16, 0.66, '');

/* tractor */
shell(TRUCK, -0.2, 6.1, 0.78, 0.98, -0.54, -0.34, 19, 0.58, '');
shell(TRUCK, -0.2, 6.1, 0.78, 0.98, 0.34, 0.54, 19, 0.58, '');
shell(TRUCK, 0.85, 2.42, 0.98, 3.32, -1.28, 1.28, 20, 0.94, '');
boxEdges(TRUCK, 0.85, 2.42, 0.98, 3.32, -1.28, 1.28, 7.5, 1.0);
shell(TRUCK, 2.42, 4.62, 0.98, 3.12, -1.28, 1.28, 20, 0.97, 'a');
boxEdges(TRUCK, 2.42, 4.62, 0.98, 3.12, -1.28, 1.28, 7.5, 1.0);
shell(TRUCK, 0.9, 2.42, 3.32, 3.86, -1.16, 1.16, 19, 0.78, 'c');
boxEdges(TRUCK, 0.9, 2.42, 3.32, 3.86, -1.16, 1.16, 7, 0.86);
shell(TRUCK, 4.62, 6.14, 1.12, 1.98, -1.22, 1.22, 26, 1.0, 'a');
boxEdges(TRUCK, 4.62, 6.14, 1.12, 1.98, -1.22, 1.22, 9, 1.04);
shell(TRUCK, 6.14, 6.34, 1.1, 1.96, -1.14, 1.14, 38, 1.08, 'a');
