/* mirrors */
shell(TRUCK, 4.26, 4.4, 1.94, 2.74, -1.64, -1.5, 36, 0.94, '');
shell(TRUCK, 4.26, 4.4, 1.94, 2.74, 1.5, 1.64, 36, 0.7, '');
beam(TRUCK, 4.33, 2.62, -1.28, 4.33, 2.62, -1.58, 34, 0.78);
beam(TRUCK, 4.33, 2.62, 1.28, 4.33, 2.62, 1.58, 34, 0.6);
/* exhaust stacks */
const stack = (zc: number, g: number) => {
	for (let q = 0; q < 220; q++) {
		const a = rr() * TAU;
		TRUCK.push({
			x: 2.28 + 0.085 * Math.cos(a),
			y: 0.95 + rr() * 3.05,
			z: zc + 0.085 * Math.sin(a),
			i: g * (0.72 + rr() * 0.34),
		});
	}
};
stack(-1.37, 0.95);
stack(1.37, 0.6);
/* fuel tanks */
const tank = (zc: number, g: number) => {
	for (let q = 0; q < 340; q++) {
		const a = rr() * TAU;
		TRUCK.push({
			x: 2.62 + rr() * 1.72,
			y: 0.86 + 0.34 * Math.sin(a),
			z: zc + 0.34 * Math.cos(a),
			i: g * (0.6 + 0.45 * Math.max(0, -Math.cos(a))),
		});
	}
};
tank(-1.25, 1);
tank(1.25, 0.55);

/* ---------------- wheels (spun per frame) ---------------- */
type Wh = {hx: number; hy: number; z: number; r: number; a: number; i: number};
const WHEELS: Wh[] = [];
const RW = 0.53;
const wheelAt = (hxp: number, zc: number, wide: number, g: number) => {
	const hw = wide / 2;
	/* tread band */
	for (let q = 0; q < 72; q++)
		WHEELS.push({
			hx: hxp, hy: RW, z: zc + (rr() - 0.5) * wide,
			r: RW * (0.952 + rr() * 0.048), a: rr() * TAU, i: g * (0.9 + rr() * 0.22),
		});
	/* near sidewall */
	for (let q = 0; q < 80; q++) {
		const rad = RW * (0.31 + 0.69 * Math.sqrt(rr()));
		WHEELS.push({
			hx: hxp, hy: RW, z: zc - hw * (0.84 + rr() * 0.16),
			r: rad, a: rr() * TAU, i: g * (0.34 + 0.5 * (rad / RW)),
		});
	}
	/* hub */
	for (let q = 0; q < 26; q++)
		WHEELS.push({
			hx: hxp, hy: RW, z: zc - hw * 0.94,
			r: RW * (0.1 + rr() * 0.19), a: rr() * TAU, i: g * 0.98,
		});
	/* spokes */
	for (let sp = 0; sp < 6; sp++) {
		const a0 = (sp / 6) * TAU;
		for (let q = 0; q < 7; q++)
			WHEELS.push({
				hx: hxp, hy: RW, z: zc - hw * 0.9,
				r: RW * (0.3 + (q / 6) * 0.4), a: a0, i: g * 0.92,
			});
	}
};
wheelAt(5.35, -1.22, 0.32, 1);
wheelAt(5.35, 1.22, 0.32, 0.5);
wheelAt(2.05, -1.2, 0.6, 1);
wheelAt(2.05, 1.2, 0.6, 0.45);
wheelAt(0.72, -1.2, 0.6, 1);
wheelAt(0.72, 1.2, 0.6, 0.45);
wheelAt(-7.2, -1.2, 0.6, 1);
wheelAt(-7.2, 1.2, 0.6, 0.45);
wheelAt(-8.45, -1.2, 0.6, 1);
wheelAt(-8.45, 1.2, 0.6, 0.45);

