/* ---------------- ground returns ---------------- */
const SPEC: {x: number; z: number; y: number; i: number}[] = [];
for (let q = 0; q < 1750; q++) {
	const z = (rr() - 0.5) * 46;
	const off = Math.abs(z) > 7.6;
	SPEC.push({
		x: -100 + rr() * 120,
		z,
		y: off ? rr() * 0.34 : rr() * 0.015,
		i: (off ? 0.34 : 0.56) * (0.45 + rr() * 0.85),
	});
}

/* ---------------- traffic ---------------- */
const mkVeh = (L: number, Wd: number, Ht: number, dens: number) => {
	const arr: Pt[] = [];
	shell(arr, -L / 2, L / 2, 0.36, Ht, -Wd / 2, Wd / 2, dens, 1, 'c');
	boxEdges(arr, -L / 2, L / 2, 0.36, Ht, -Wd / 2, Wd / 2, 3.6, 1.05);
	return arr;
};
const CAR = mkVeh(4.6, 1.86, 1.5, 6);
const VAN = mkVeh(5.9, 2.12, 2.34, 5);

